ConfigurationParameters.ScriptContent:
param(
$certificateResponse,
$storeTypeResponse
)

$certificateResponse = $certificateResponse | ConvertFrom-Json
$storeTypeResponse = $storeTypeResponse | ConvertFrom-Json

# COMPATIBILITY NOTE: this should be uncommented for KF Command Versions 12.2 and below, which require accessing the Result object
# need to access the Result element of the response objects in KF 11 -> 12.2
# $certificateResponse = $certificateResponse.Result
# $storeTypeResponse = $storeTypeResponse.Result

# storeTypeResponse returns array of results, need to select specific result
$storeTypeResponse = $storeTypeResponse[0]

$result = @{}

$foundSans = ""

# read sans from cert info
$sans = $certificateResponse.SubjectAltNameElements
foreach($san in $sans)
{
    if ($san.Type -eq 2) #include only dns sans (type 2)
    {
        if ($foundSans) # if Sans is non-empty
        {
            $foundSans = $foundSans + "&" # add ampersand delimiter for additional DNS SANs
        }
        $foundSans = $foundSans + $san.Value
    }
}

$result.Add("foundSans", $foundSans)

# get Location / Store Id to lookup Orchestrator ID
$locations = $certificateResponse.Locations
foreach($location in $locations)
{
    if ($location.StoreType -eq $storeTypeResponse.StoreType)
    {
        $result.Add("CertStoreId", $location.CertStoreId)
    }
}

return $result
